custom_css:
/* ── Visitor Pre-Registration portal ──────────────────────────────────────────
   Public-facing form. Restyles Frappe's v16 web form without replacing any of
   its markup, so the framework keeps owning validation, uploads and save.

   The alignment fix is the `display: contents` block below: Frappe nests fields
   as .section-body > .form-column > form > .form-group, and flexed columns let
   the two sides drift out of step. Flattening both wrappers turns the fields
   into direct grid items, so every row lines up regardless of how many fields
   sit in each column.
   ------------------------------------------------------------------------- */

:root {
  /* Overridden per-site by the theme block that get_context injects. These are
     only the fallback, so the page still renders if settings are unreadable. */
  --vr-brand: #1a56db;
  --vr-brand-dark: #1443ae;
  --vr-brand-soft: #e4ebfb;
  --vr-brand-border: #a8bff1;
  --vr-brand-rgb: 26, 86, 219;
  --vr-on-brand: #ffffff;
  --vr-brand-tint: rgba(26, 86, 219, 0.08);
  --vr-ink: #0f172a;
  --vr-muted: #64748b;
  --vr-faint: #94a3b8;
  --vr-line: #e2e8f0;
  --vr-surface: #ffffff;
  --vr-canvas: #f1f5f9;
  --vr-field-bg: #ffffff;
  --vr-field-bg-off: #f8fafc;
  --vr-ok: #059669;
  --vr-danger: #dc2626;
  --vr-radius: 14px;
  --vr-radius-sm: 10px;
  --vr-field-h: 46px;
}

body {
  background: var(--vr-canvas);
  color: var(--vr-ink);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  -webkit-font-smoothing: antialiased;
}

.page_content { padding: 1.75rem 0 6rem; }
.page-footer, footer { display: none; }

/* This is a single-purpose public page reached from an emailed link — the site
   navbar (Home / Login) is noise for a visitor and its mobile toggle renders as
   an empty box. */
.navbar, header.sticky-top { display: none !important; }
.web-form-container { max-width: 860px; margin: 0 auto; padding: 0 1rem; }

/* ── header ───────────────────────────────────────────────────────────────── */
.web-form-head { padding-bottom: 0; border: none; }
.web-form-header { text-align: center; margin-bottom: 0.75rem; }

.web-form-head .title {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.2rem;
  text-align: center;
}
.web-form-head .title .web-form-title { width: 100%; }
.web-form-head .title .web-form-actions { display: none; }
.web-form-head .indicator-pill,
.web-form-header .indicator-pill { display: none !important; }

.web-form-title h1 {
  font-size: 1.7rem;
  font-weight: 750;
  letter-spacing: -0.025em;
  color: var(--vr-ink);
  margin-bottom: 0.15rem;
  /* Frappe truncates the page title with ellipsis; a public form should wrap
     it instead of hiding half the heading on a phone. */
  white-space: normal;
  overflow: visible;
  text-overflow: clip;
  overflow-wrap: break-word;
}

.web-form-introduction {
  max-width: 640px;
  margin: 0 auto;
  font-size: 0.9rem;
  line-height: 1.55;
  color: var(--vr-muted);
}
.web-form-introduction p { margin-bottom: 0.5rem; }
.web-form-introduction p:last-child { margin-bottom: 0; }

/* ── brand lockup ─────────────────────────────────────────────────────────── */
.vm-brand {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  margin-bottom: 0.85rem;
}
.vm-brand-logo { max-height: 40px; max-width: 190px; width: auto; object-fit: contain; }
.vm-brand-name {
  font-size: 0.95rem;
  font-weight: 700;
  letter-spacing: -0.01em;
  color: var(--vr-ink);
}
.vm-portal-footer {
  margin-top: 1rem;
  font-size: 0.78rem;
  line-height: 1.5;
  color: var(--vr-faint);
  text-align: center;
}

/* ── the form card ────────────────────────────────────────────────────────── */
.web-form {
  background: var(--vr-surface);
  border: 1px solid var(--vr-line);
  border-radius: 20px;
  padding: 0.5rem 1.75rem 1.5rem;
  box-shadow: 0 1px 2px rgba(15, 23, 42, 0.04), 0 12px 32px rgba(15, 23, 42, 0.05);
  margin-top: 1.25rem;
  counter-reset: vr-step;
}

/* ── sections ─────────────────────────────────────────────────────────────── */
.form-section {
  margin: 0;
  padding: 1.5rem 0 0.35rem;
  border: none;
  background: transparent;
}

/* A section whose fields are all hidden must not leave a stray divider. */
.form-section:not(:has(.section-head)) { display: none !important; }

/* Separator only between two sections that both render — :first-of-type would
   match a hidden one and leave a rule above the first visible section. */
.form-section:has(.section-head) ~ .form-section:has(.section-head) {
  border-top: 1px solid var(--vr-line);
}

.section-head {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 0.95rem;
  font-weight: 700;
  letter-spacing: -0.01em;
  text-transform: none;
  color: var(--vr-ink);
  margin-bottom: 1.15rem;
  padding-bottom: 0;
  border-bottom: none;
}

/* numbered step chip */
.form-section .section-head::before {
  counter-increment: vr-step;
  content: counter(vr-step);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  flex-shrink: 0;
  border-radius: 50%;
  background: var(--vr-brand);
  color: var(--vr-on-brand);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0;
}
.section-head .collapse-indicator { display: none; }

/* ── alignment: flatten Frappe's column wrappers into one grid ────────────── */
.web-form .form-section .section-body {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  column-gap: 1.5rem;
  row-gap: 0.35rem;
  align-items: start;
}
.web-form .form-section .section-body > .form-column,
.web-form .form-section .section-body > .form-column > form { display: contents; }

/* fields that read better across the full width */
.web-form [data-fieldname="purpose_of_visit"],
.web-form [data-fieldname="protocol_notes"],
.web-form [data-fieldname="interview_panel"],
.web-form [data-fieldname="tools_list"],
.web-form [data-fieldname="items_carried"] { grid-column: 1 / -1; }

/* ── fields ───────────────────────────────────────────────────────────────── */
.form-group { margin-bottom: 1rem; }

.control-label {
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--vr-ink);
  margin-bottom: 6px;
  letter-spacing: -0.005em;
}
.control-label .reqd,
.control-label > .text-danger { color: var(--vr-danger); }

.form-control,
.form-select,
.like-disabled-input {
  min-height: var(--vr-field-h);
  border-radius: var(--vr-radius-sm) !important;
  border: 1px solid var(--vr-line) !important;
  background: var(--vr-field-bg) !important;
  font-size: 0.92rem;
  color: var(--vr-ink);
  padding: 0.5rem 0.85rem;
  box-shadow: none !important;
  transition: border-color 0.15s ease, box-shadow 0.15s ease, background 0.15s ease;
}
textarea.form-control { min-height: 96px; padding-top: 0.6rem; line-height: 1.5; }

.form-control:hover:not(:disabled):not([readonly]) { border-color: #cbd5e1 !important; }
.form-control:focus,
.form-select:focus {
  border-color: var(--vr-brand) !important;
  box-shadow: 0 0 0 3px var(--vr-brand-tint) !important;
  outline: none;
}
.form-control:disabled,
.form-control[readonly] {
  background: #f8fafc !important;
  color: var(--vr-muted);
  cursor: not-allowed;
}

.help-box,
.help-box.small.text-muted {
  font-size: 0.755rem;
  line-height: 1.45;
  color: var(--vr-faint) !important;
  margin-top: 5px;
}

.control-input-wrapper .control-value.like-disabled-input { display: none !important; }

/* Frappe applies .has-error to mandatory-empty fields on load, so styling it
   would paint every untouched field red. Flag the field only once the visitor
   has actually left it empty. */
.has-error .form-control:not(:placeholder-shown),
.has-error .form-control:focus { border-color: var(--vr-danger) !important; }

/* ── uploads: turn the bare Attach button into a real dropzone ─────────────── */
.frappe-control[data-fieldtype="Attach"] .control-input,
.frappe-control[data-fieldtype="Attach Image"] .control-input { width: 100%; }

.frappe-control[data-fieldtype="Attach"] .btn-sm,
.frappe-control[data-fieldtype="Attach Image"] .btn-sm,
.frappe-control[data-fieldtype="Attach"] .btn-file-upload,
.frappe-control[data-fieldtype="Attach Image"] .btn-file-upload {
  display: flex !important;
  align-items: center;
  justify-content: center;
  gap: 8px;
  width: 100%;
  min-height: 84px;
  padding: 0.75rem 1rem;
  border: 1.5px dashed #cbd5e1 !important;
  border-radius: var(--vr-radius-sm);
  background: #fafbfc !important;
  color: var(--vr-brand) !important;
  font-size: 0.86rem;
  font-weight: 600;
  transition: border-color 0.15s ease, background 0.15s ease;
}
.frappe-control[data-fieldtype="Attach"] .btn-sm:hover,
.frappe-control[data-fieldtype="Attach Image"] .btn-sm:hover {
  border-color: var(--vr-brand) !important;
  background: var(--vr-brand-tint) !important;
}
.attached-file {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 56px;
  padding: 0.6rem 0.85rem;
  border: 1px solid #bbf7d0 !important;
  border-radius: var(--vr-radius-sm) !important;
  background: #f0fdf4 !important;
  font-size: 0.83rem;
}
.attached-file .attached-file-link {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--vr-ok);
  font-weight: 600;
}

/* ── checkboxes ───────────────────────────────────────────────────────────── */
.frappe-control[data-fieldtype="Check"] .control-input-wrapper {
  display: flex;
  align-items: center;
  gap: 9px;
  min-height: var(--vr-field-h);
}
.frappe-control[data-fieldtype="Check"] input[type="checkbox"] {
  width: 18px;
  height: 18px;
  accent-color: var(--vr-brand);
  cursor: pointer;
}
.frappe-control[data-fieldtype="Check"] .label-area {
  font-size: 0.88rem;
  font-weight: 500;
  cursor: pointer;
}

/* ── status panels (JS-driven) ────────────────────────────────────────────── */
.vm-status-panel {
  display: flex;
  gap: 12px;
  margin: 0 0 1.25rem;
  padding: 0.95rem 1.15rem;
  border-radius: var(--vr-radius-sm);
  border: 1px solid var(--vr-line);
  border-left-width: 4px;
  text-align: left;
}
.vm-status-title { font-size: 0.9rem; font-weight: 700; margin-bottom: 3px; }
.vm-status-message { font-size: 0.84rem; line-height: 1.5; color: var(--vr-muted); }
.vm-status-success { background: #f0fdf4; border-color: #bbf7d0; border-left-color: var(--vr-ok); }
.vm-status-success .vm-status-title { color: var(--vr-ok); }
.vm-status-error { background: #fef2f2; border-color: #fecaca; border-left-color: var(--vr-danger); }
.vm-status-error .vm-status-title { color: var(--vr-danger); }

/* ── host-locked fields ───────────────────────────────────────────────────── */
.vm-locked-sections { margin-bottom: 1rem; }
.vm-locked-section {
  padding: 1.15rem 1.25rem;
  border: 1px solid var(--vr-line);
  border-radius: var(--vr-radius);
  background: #fafbfc;
}
.vm-locked-section-title {
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--vr-brand);
  margin-bottom: 0.9rem;
  padding-bottom: 0.5rem;
  border-bottom: 1px solid var(--vr-line);
}
.vm-locked-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }
.vm-locked-card {
  padding: 10px 14px;
  border: 1px solid var(--vr-line);
  border-radius: var(--vr-radius-sm);
  background: var(--vr-surface);
}
.vm-locked-label {
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--vr-faint);
  margin-bottom: 3px;
}
.vm-locked-value { font-size: 0.92rem; font-weight: 600; color: var(--vr-ink); }

.vm-locked-display {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: var(--vr-field-h);
  padding: 0.5rem 0.85rem;
  border-radius: var(--vr-radius-sm);
  border: 1px solid var(--vr-brand-border);
  background: var(--vr-brand-soft);
  color: var(--vr-ink);
  font-weight: 600;
  font-size: 0.92rem;
}
.vm-locked-display::before {
  content: '';
  display: inline-block;
  width: 13px;
  height: 13px;
  flex-shrink: 0;
  /* currentColor keeps the padlock on-brand whatever the site's colour is */
  background-color: currentColor;
  -webkit-mask-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><path d='M12 1a5 5 0 0 0-5 5v3H5a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-9a2 2 0 0 0-2-2h-2V6a5 5 0 0 0-5-5zm-3 8V6a3 3 0 0 1 6 0v3H9z'/></svg>");
  mask-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><path d='M12 1a5 5 0 0 0-5 5v3H5a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-9a2 2 0 0 0-2-2h-2V6a5 5 0 0 0-5-5zm-3 8V6a3 3 0 0 1 6 0v3H9z'/></svg>");
  -webkit-mask-size: contain;
  mask-size: contain;
  color: var(--vr-brand);
}
.vm-locked-field .control-input { display: none !important; }
.vm-host-field .control-label::after {
  content: 'Set by host';
  margin-left: 6px;
  font-size: 0.64rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--vr-brand);
  background: var(--vr-brand-tint);
  padding: 2px 7px;
  border-radius: 4px;
  vertical-align: 1px;
}

.vm-mobile-error { margin-top: 5px; font-size: 0.76rem; color: var(--vr-danger); display: none; }
.vm-mobile-error.visible { display: block; }

/* ── injected blocks (visitor items, hospitality) ─────────────────────────── */
.vm-custom-block {
  grid-column: 1 / -1;
  margin: 0.35rem 0 1.15rem;
  padding: 1.15rem 1.25rem;
  border: 1px solid var(--vr-line);
  border-radius: var(--vr-radius);
  background: #fafbfc;
}
.vm-items-intro {
  font-size: 0.86rem;
  line-height: 1.55;
  color: var(--vr-muted);
  margin: 0 0 0.85rem;
}
/* The items block is injected outside the form-section flow, so give it the
   same visual weight as a real section instead of a nested card. */
.vm-visitor-items-section.vm-custom-block {
  margin: 0;
  padding: 1.5rem 0 0.35rem;
  border: none;
  border-top: 1px solid var(--vr-line);
  border-radius: 0;
  background: transparent;
}
.vm-visitor-items-section .vm-locked-section-title {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 0.95rem;
  font-weight: 700;
  letter-spacing: -0.01em;
  text-transform: none;
  color: var(--vr-ink);
  margin-bottom: 0.5rem;
  padding-bottom: 0;
  border-bottom: none;
}
.vm-visitor-items-section .vm-locked-section-title::before {
  content: '4';
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  flex-shrink: 0;
  border-radius: 50%;
  background: var(--vr-brand);
  color: var(--vr-on-brand);
  font-size: 0.75rem;
  font-weight: 700;
}
.vm-visitor-items-list { display: grid; gap: 10px; }
.vm-visitor-item-row,
.vm-visitor-item-row.vm-hospitality-card {
  padding: 0.9rem 1rem;
  border: 1px solid var(--vr-line);
  border-radius: var(--vr-radius-sm);
  background: var(--vr-surface);
}
.vm-item-name { font-weight: 600; font-size: 0.9rem; }
.vm-hospitality-card {
  padding: 0.9rem 1rem;
  border: 1px solid var(--vr-brand-border);
  border-radius: var(--vr-radius-sm);
  background: var(--vr-brand-soft);
  font-size: 0.86rem;
}

/* ── success ──────────────────────────────────────────────────────────────── */
.vm-success-panel {
  margin: 1rem auto;
  max-width: 620px;
  padding: 1.75rem 1.5rem;
  border-radius: var(--vr-radius);
  background: #f0fdf4;
  border: 1px solid #bbf7d0;
  text-align: center;
}
.vm-success-ref {
  display: inline-block;
  margin-top: 0.75rem;
  padding: 7px 15px;
  border-radius: var(--vr-radius-sm);
  background: var(--vr-surface);
  border: 1px solid #bbf7d0;
  font-family: 'SF Mono', Menlo, Consolas, monospace;
  font-weight: 700;
  color: var(--vr-ok);
}
.vm-success-next {
  margin-top: 1.15rem;
  font-size: 0.87rem;
  color: var(--vr-muted);
  line-height: 1.6;
  text-align: left;
}
.vm-success-next ol { margin: 0.5rem 0 0 1.15rem; padding: 0; }
.vm-success-next li { margin-bottom: 5px; }

/* ── footer / submit ──────────────────────────────────────────────────────── */
.web-form-footer {
  margin-top: 1.25rem;
  padding-top: 1.25rem;
  border-top: 1px solid var(--vr-line);
}
.web-form-footer .left-area { display: none; }

.discard-btn.btn,
.submit-btn.btn {
  min-height: 48px;
  border-radius: var(--vr-radius-sm);
  padding: 10px 28px;
  font-weight: 650;
  font-size: 0.9rem;
  letter-spacing: -0.005em;
  transition: background 0.15s ease, box-shadow 0.15s ease, transform 0.05s ease;
}
.discard-btn.btn { background: var(--vr-surface); border: 1px solid var(--vr-line); color: var(--vr-ink); }
.submit-btn.btn {
  background: var(--vr-brand);
  border: none;
  color: var(--vr-on-brand);
  box-shadow: 0 2px 8px rgba(var(--vr-brand-rgb), 0.22);
}
.submit-btn.btn:hover { background: var(--vr-brand-dark); box-shadow: 0 4px 14px rgba(var(--vr-brand-rgb), 0.3); }
.submit-btn.btn:active { transform: translateY(1px); }
.submit-btn.btn:focus-visible,
.discard-btn.btn:focus-visible { outline: 3px solid var(--vr-brand-tint); outline-offset: 2px; }

.vm-form-hidden { display: none !important; }

/* ── responsive ───────────────────────────────────────────────────────────── */
@media (max-width: 768px) {
  .page_content { padding: 0.75rem 0 7rem; }
  .web-form-container { padding: 0 0.75rem; }
  .web-form { padding: 0.35rem 1.1rem 1.25rem; border-radius: 16px; }
  .web-form-title h1 { font-size: 1.35rem; }
  .web-form-introduction { font-size: 0.85rem; }

  /* one field per row on a phone */
  .web-form .form-section .section-body { grid-template-columns: 1fr; row-gap: 0; }
  .vm-locked-grid { grid-template-columns: 1fr; }
  .form-section { padding-top: 1.25rem; }

  /* keep the primary action reachable without scrolling to the end */
  .web-form-footer {
    position: sticky;
    bottom: 0;
    margin: 1rem -1.1rem -1.25rem;
    padding: 0.85rem 1.1rem calc(0.85rem + env(safe-area-inset-bottom, 0px));
    background: rgba(255, 255, 255, 0.97);
    backdrop-filter: blur(8px);
    border-top: 1px solid var(--vr-line);
    z-index: 5;
  }
  .web-form-footer .right-area { display: grid; gap: 8px; width: 100%; }
  .submit-btn.btn, .discard-btn.btn { width: 100%; }
}

@media (prefers-reduced-motion: reduce) {
  * { transition: none !important; animation: none !important; }
}

/* ── dark mode ────────────────────────────────────────────────────────────────
   Only the neutrals flip; the brand colour is whatever the site configured, so
   it stays recognisable. Surfaces lighten with depth rather than going pure
   black, which keeps fields legible on OLED phones.

   Frappe's own website bundle paints .web-form and friends through a 5-class
   selector we cannot outrank without !important everywhere. Rather than fight
   it rule by rule, we retarget the core custom properties it reads — one
   change covers the card, the footer, the skeleton and anything core adds
   later. */
@media (prefers-color-scheme: dark) {
  :root {
    --vr-ink: #e6edf6;
    --vr-muted: #97a4b8;
    --vr-faint: #6f7d92;
    --vr-line: #263243;
    --vr-surface: #131a24;
    --vr-canvas: #0b1017;
    --vr-field-bg: #0f1620;
    --vr-field-bg-off: #0c121a;

    /* core Frappe tokens */
    --fg-color: #131a24;
    --card-bg: #131a24;
    --bg-color: #0b1017;
    --control-bg: #0f1620;
    --subtle-fg: #1a2331;
    --border-color: #263243;
    --text-color: #e6edf6;
    --text-muted: #97a4b8;
    --heading-color: #e6edf6;
    --gray-300: #334054;
  }

  .web-form,
  .web-form-header { box-shadow: 0 1px 2px rgba(0, 0, 0, 0.5), 0 12px 32px rgba(0, 0, 0, 0.35); }

  .form-control,
  .form-select,
  .like-disabled-input {
    border-color: var(--vr-line) !important;
    color: var(--vr-ink);
  }
  .form-control::placeholder { color: var(--vr-faint); }
  .form-control:hover:not(:disabled):not([readonly]) { border-color: #33405480 !important; }
  .form-control:disabled,
  .form-control[readonly] { background: var(--vr-field-bg-off) !important; color: var(--vr-muted); }

  .frappe-control[data-fieldtype="Attach"] .btn-sm,
  .frappe-control[data-fieldtype="Attach Image"] .btn-sm,
  .frappe-control[data-fieldtype="Attach"] .btn-file-upload,
  .frappe-control[data-fieldtype="Attach Image"] .btn-file-upload {
    background: var(--vr-field-bg) !important;
    border-color: #33405480 !important;
    color: var(--vr-muted);
  }
  .attached-file { background: #0d1f18 !important; border-color: #1c4532 !important; }

  .vm-locked-section,
  .vm-custom-block { background: var(--vr-field-bg); }
  .vm-locked-display,
  .vm-hospitality-card {
    background: rgba(var(--vr-brand-rgb), 0.14);
    border-color: rgba(var(--vr-brand-rgb), 0.4);
  }
  .vm-host-field .control-label::after { background: rgba(var(--vr-brand-rgb), 0.18); }

  .vm-status-success,
  .vm-success-panel { background: #0d1f18; border-color: #1c4532; }
  .vm-status-error { background: #26120f; border-color: #4c1d1d; }
  .vm-success-ref { border-color: #1c4532; }

  .discard-btn.btn { border-color: var(--vr-line); color: var(--vr-ink); }
  .web-form-footer { background: rgba(19, 26, 36, 0.97); }
}

/* ── surfaces core paints from literals, not from theme tokens ─────────────────
   Two rules in Frappe's website bundle set a colour that never changes with the
   theme:

     h1..h6        { color: rgb(23,23,23) }   ignores --heading-color
     .modal-content{ background: #fff     }   ignores --fg-color / --card-bg

   In dark mode the first left every heading near-black on a near-black ground
   (1.03:1 — the "Submitted" confirmation was invisible), and the second left
   msgprint dialogs showing near-white body text on white (1.18:1), so a visitor
   who mistyped their ID saw an apparently empty error box.

   Taking both from the same tokens as the surface behind them keeps each theme
   internally consistent. */
h1, h2, h3, h4, h5, h6 {
  color: var(--vr-ink);
}

.modal-content {
  background: var(--vr-surface);
  color: var(--vr-ink);
  border: 1px solid var(--vr-line);
}
.modal .modal-header,
.modal .modal-footer {
  border-color: var(--vr-line);
}
.modal .modal-title,
.modal .msgprint,
.modal .modal-body {
  color: var(--vr-ink);
}
